import{_ as d,a as e,c as r,ac as a}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","frontmatter":{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","splitFrom":"systems/linux/common-commands.md","showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Linux 常用命令：用途、参数与操作边界","summary":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","status":"active","related":[{"title":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","link":"/systems/linux/common-commands-part-01","kind":"命令与系统观察","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07"}},"headers":[],"relativePath":"systems/linux/common-commands-part-06.md","filePath":"systems/linux/common-commands-part-06.md"}'),o={name:"systems/linux/common-commands-part-06.md"};function c(m,t,p,n,i,s){return e(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="linux-常用命令-用途、参数与操作边界-·-按发行版选择包管理器至备份与同步" tabindex="-1">Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界-·-按发行版选择包管理器至备份与同步" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步&quot;">​</a></h1><p><a href="/systems/linux/common-commands">返回分篇目录</a></p><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><h2 id="part-2-按发行版选择包管理器" tabindex="-1">按发行版选择包管理器 <a class="header-anchor" href="#part-2-按发行版选择包管理器" aria-label="Permalink to &quot;按发行版选择包管理器 {#part-2-按发行版选择包管理器}&quot;">​</a></h2><p>先确认发行版，再选择对应的一组命令，不能混用 RPM/DEB。优先包管理器解析依赖；批量升级先审查事务和恢复路径。</p><h3 id="part-2-fedora-red-hat-rpm-查询与校验" tabindex="-1">Fedora / Red Hat：RPM 查询与校验 <a class="header-anchor" href="#part-2-fedora-red-hat-rpm-查询与校验" aria-label="Permalink to &quot;Fedora / Red Hat：RPM 查询与校验 {#part-2-fedora-red-hat-rpm-查询与校验}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>rpm -ivh package.rpm</code></td><td>安装一个rpm包</td></tr><tr><td><code>rpm -U package.rpm</code></td><td>升级 RPM 包；配置文件处理需核对包策略与事务结果</td></tr><tr><td><code>rpm -F package.rpm</code></td><td>更新一个确定已经安装的rpm包</td></tr><tr><td><code>rpm -e package_name</code></td><td>删除一个rpm包</td></tr><tr><td><code>rpm -qa</code></td><td>显示系统中所有已经安装的rpm包</td></tr><tr><td><code>rpm -qa | grep httpd</code></td><td>显示所有名称中包含 &quot;httpd&quot; 字样的rpm包</td></tr><tr><td><code>rpm -qi package_name</code></td><td>获取一个已安装包的特殊信息</td></tr><tr><td><code>rpm -qg &quot;System Environment/Daemons&quot;</code></td><td>显示一个组件的rpm包</td></tr><tr><td><code>rpm -ql package_name</code></td><td>显示一个已经安装的rpm包提供的文件列表</td></tr><tr><td><code>rpm -qc package_name</code></td><td>显示一个已经安装的rpm包提供的配置文件列表</td></tr><tr><td><code>rpm -q package_name --whatrequires</code></td><td>显示与一个rpm包存在依赖关系的列表</td></tr><tr><td><code>rpm -q package_name --scripts</code></td><td>显示在安装/删除期间所执行的脚本l</td></tr><tr><td><code>rpm -q package_name --changelog</code></td><td>显示一个rpm包的修改历史</td></tr><tr><td><code>rpm -qf /etc/httpd/conf/httpd.conf</code></td><td>确认所给的文件由哪个rpm包所提供</td></tr><tr><td><code>rpm -qp package.rpm -l</code></td><td>显示由一个尚未安装的rpm包提供的文件列表</td></tr><tr><td><code>rpm --import /media/cdrom/RPM-GPG-KEY</code></td><td>导入公钥数字证书</td></tr><tr><td><code>rpm --checksig package.rpm</code></td><td>确认一个rpm包的完整性</td></tr><tr><td><code>rpm -V package_name</code></td><td>检查文件尺寸、 许可、类型、所有者、群组、MD5检查以及最后修改时间</td></tr><tr><td><code>rpm -Va</code></td><td>检查系统中所有已安装的rpm包- 小心使用</td></tr><tr><td><code>rpm2cpio package.rpm | cpio --extract --make-directories *bin*</code></td><td>从 RPM 归档提取匹配文件；不运行其中程序</td></tr><tr><td><code>rpm -ivh /usr/src/redhat/RPMS/`arch`/package.rpm</code></td><td>从一个rpm源码安装一个构建好的包</td></tr><tr><td><code>rpmbuild --rebuild package_name.src.rpm</code></td><td>从一个rpm源码构建一个 rpm 包</td></tr></tbody></table><h3 id="part-2-yum-安装、更新与缓存" tabindex="-1">YUM 安装、更新与缓存 <a class="header-anchor" href="#part-2-yum-安装、更新与缓存" aria-label="Permalink to &quot;YUM 安装、更新与缓存 {#part-2-yum-安装、更新与缓存}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>yum install package_name</code></td><td>下载并安装一个rpm包</td></tr><tr><td><code>yum localinstall package_name.rpm</code></td><td>将安装一个rpm包，使用你自己的软件仓库为你解决所有依赖关系</td></tr><tr><td><code>yum update</code></td><td>更新系统软件包；先审查事务范围</td></tr><tr><td><code>yum update package_name</code></td><td>更新一个rpm包</td></tr><tr><td><code>yum remove package_name</code></td><td>删除一个rpm包</td></tr><tr><td><code>yum list</code></td><td>列出当前系统中安装的所有包</td></tr><tr><td><code>yum search package_name</code></td><td>在rpm仓库中搜寻软件包</td></tr><tr><td><code>yum clean packages</code></td><td>清理rpm缓存删除下载的包</td></tr><tr><td><code>yum clean headers</code></td><td>清理缓存的软件包头信息</td></tr><tr><td><code>yum clean all</code></td><td>删除所有缓存的包和头文件</td></tr></tbody></table><h3 id="part-2-debian-ubuntu-deb-查询" tabindex="-1">Debian / Ubuntu：DEB 查询 <a class="header-anchor" href="#part-2-debian-ubuntu-deb-查询" aria-label="Permalink to &quot;Debian / Ubuntu：DEB 查询 {#part-2-debian-ubuntu-deb-查询}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>dpkg -i package.deb</code></td><td>安装/更新一个 deb 包</td></tr><tr><td><code>dpkg -r package_name</code></td><td>从系统删除一个 deb 包</td></tr><tr><td><code>dpkg -l</code></td><td>显示系统中所有已经安装的 deb 包</td></tr><tr><td><code>dpkg -l | grep httpd</code></td><td>显示所有名称中包含 &quot;httpd&quot; 字样的deb包</td></tr><tr><td><code>dpkg -s package_name</code></td><td>获得已经安装在系统中一个特殊包的信息</td></tr><tr><td><code>dpkg -L package_name</code></td><td>显示系统中已经安装的一个deb包所提供的文件列表</td></tr><tr><td><code>dpkg --contents package.deb</code></td><td>显示尚未安装的一个包所提供的文件列表</td></tr><tr><td><code>dpkg -S /bin/ping</code></td><td>确认所给的文件由哪个deb包提供</td></tr></tbody></table><h3 id="part-2-apt-索引与软件包" tabindex="-1">APT 索引与软件包 <a class="header-anchor" href="#part-2-apt-索引与软件包" aria-label="Permalink to &quot;APT 索引与软件包 {#part-2-apt-索引与软件包}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>apt-get install package_name</code></td><td>安装/更新一个 deb 包</td></tr><tr><td><code>apt-get update</code></td><td>更新软件包索引</td></tr><tr><td><code>apt-get upgrade</code></td><td>升级所有已安装的软件</td></tr><tr><td><code>apt-get remove package_name</code></td><td>从系统删除一个deb包</td></tr><tr><td><code>apt-get check</code></td><td>检查软件包依赖是否损坏</td></tr><tr><td><code>apt-get clean</code></td><td>从下载的软件包中清理缓存</td></tr><tr><td><code>apt-cache search searched-package</code></td><td>返回包含所要搜索字符串的软件包名称</td></tr></tbody></table><h2 id="part-2-网络接口与路由" tabindex="-1">网络接口与路由 <a class="header-anchor" href="#part-2-网络接口与路由" aria-label="Permalink to &quot;网络接口与路由 {#part-2-网络接口与路由}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>ifconfig eth0</code></td><td>显示一个以太网卡的配置</td></tr><tr><td><code>ifup eth0</code></td><td>启用一个 &#39;eth0&#39; 网络设备</td></tr><tr><td><code>ifdown eth0</code></td><td>禁用一个 &#39;eth0&#39; 网络设备</td></tr><tr><td><code>ifconfig eth0 192.168.1.1 netmask 255.255.255.0</code></td><td>控制IP地址</td></tr><tr><td><code>ifconfig eth0 promisc</code></td><td>设置 &#39;eth0&#39; 成混杂模式以嗅探数据包 (sniffing)</td></tr><tr><td><code>dhclient eth0</code></td><td>以dhcp模式启用 &#39;eth0&#39;</td></tr><tr><td><code>route -n</code></td><td>显示路由表</td></tr><tr><td><code>route add -net 0/0 gw &lt;gateway&gt;</code></td><td>旧 route 语法设置默认路由</td></tr><tr><td><code>route add -net 192.168.0.0 netmask 255.255.0.0 gw 192.168.1.1</code></td><td>旧 route 静态路由例；网关按实际环境替换</td></tr></tbody></table><p>这些是 ifconfig/route 旧工具例。远程关闭网卡或改变地址可能立即中断 SSH；CentOS 7 的失败实验与恢复边界见 <a href="/systems/linux/troubleshooting#part-1-legacy-systems-network-experiment">网络管理记录</a>。</p><h2 id="part-2-备份与同步" tabindex="-1">备份与同步 <a class="header-anchor" href="#part-2-备份与同步" aria-label="Permalink to &quot;备份与同步 {#part-2-备份与同步}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途与边界</th></tr></thead><tbody><tr><td><code>dump -0aj -f /tmp/home0.bak /home</code></td><td>制作一个 &#39;/home&#39; 目录的完整备份</td></tr><tr><td><code>dump -1aj -f /tmp/home0.bak /home</code></td><td>制作 /home 的 level 1 增量备份；需已有基线</td></tr><tr><td><code>restore -if /tmp/home0.bak</code></td><td>还原一个交互式备份</td></tr><tr><td><code>rsync -rogpav --delete /home /tmp</code></td><td>同步两边的目录</td></tr><tr><td><code>rsync -rogpav -e ssh --delete /home ip_address:/tmp</code></td><td>通过SSH通道rsync</td></tr><tr><td><code>rsync -az -e ssh --delete ip_addr:/home/public /home/local</code></td><td>通过ssh和压缩将一个远程目录同步到本地目录</td></tr><tr><td><code>rsync -az -e ssh --delete /home/local ip_addr:/home/public</code></td><td>通过ssh和压缩将本地目录同步到远程目录</td></tr><tr><td><code>dd bs=1M if=/dev/hda | gzip | ssh user@ip_addr &#39;dd of=hda.gz&#39;</code></td><td>通过ssh在远程主机上执行一次备份本地磁盘的操作</td></tr><tr><td><code>dd if=/dev/sda of=/tmp/file1</code></td><td>备份磁盘内容到一个文件</td></tr><tr><td><code>tar -Puf backup.tar /home/user</code></td><td>向已有归档追加较新文件；-P 保留绝对路径，解包前核对路径</td></tr><tr><td><code>( cd /tmp/local/ &amp;&amp; tar c . ) | ssh -C user@ip_addr &#39;cd /home/share/ &amp;&amp; tar x -p&#39;</code></td><td>通过ssh在远程目录中复制一个目录内容</td></tr><tr><td><code>( tar c /home ) | ssh -C user@ip_addr &#39;cd /home/backup-home &amp;&amp; tar x -p&#39;</code></td><td>通过ssh在远程目录中复制一个本地目录</td></tr><tr><td><code>tar cf - . | (cd /tmp/backup ; tar xf - )</code></td><td>本地将一个目录复制到另一个地方，保留原有权限及链接</td></tr><tr><td><code>find /home/user1 -name &#39;*.txt&#39; | xargs cp -av --target-directory=/home/backup/ --parents</code></td><td>从一个目录查找并复制所有以 &#39;.txt&#39; 结尾的文件到另一个目录</td></tr><tr><td><code>find /var/log -name &#39;*.log&#39; | tar cv --files-from=- | bzip2 &gt; log.tar.bz2</code></td><td>查找所有以 &#39;.log&#39; 结尾的文件并做成一个bzip包</td></tr><tr><td><code>dd if=/dev/hda of=/dev/fd0 bs=512 count=1</code></td><td>做一个将 MBR (Master Boot Record)内容复制到软盘的动作</td></tr><tr><td><code>dd if=/dev/fd0 of=/dev/hda bs=512 count=1</code></td><td>从已经保存到软盘的备份中恢复MBR内容</td></tr></tbody></table><p>同步、归档、块设备镜像是不同方案。<code>rsync --delete</code> 会删除目标多余项，先对同样参数执行 <code>--dry-run</code> 并核对方向；<code>dd</code> 必须逐字确认 if/of。备份完成还应按所选方案验证可读取/恢复，不能只看文件生成。</p>',19)])])}const u=d(o,[["render",c]]);export{h as __pageData,u as default};
